INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (1, 1, 'Read but No Reply', 'Relationships', 'Mind Reading', '', '{\"day\":1,\"phase\":1,\"title\":\"Read but No Reply\",\"domain\":\"Relationships\",\"mission\":\"Don\'t let your mind write the story before the facts.\",\"learning_objective\":\"Separate Facts from Stories\",\"difficulty\":\"Beginner\",\"emotional_intensity\":\"Low\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Detect\",\"primary_trap\":\"Mind Reading\",\"secondary_trap\":null,\"scenario_text\":\"Ananya sends her husband a message during lunch asking him to call when he is free.\\nHe reads the message.\\nThree hours pass.\\nThere is still no reply.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"Your brain creates stories automatically.\\nYour first responsibility is to separate them from facts.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story/assumptions your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: He read my message three hours ago and hasn\'t replied.\\nStory/assumptions: He is upset with me and is ignoring me.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"}],\"correct_option_key\":\"mind_reading\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Mind Reading.\\nThe only confirmed fact is that there has been no reply.\\nThe story is that he is upset and deliberately ignoring her.\\nThere is no evidence to support that conclusion.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask \\\"What happened?\\\" before asking \\\"How are you feeling?\\\" or \\\"What\'s bothering you?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one more explanation that also fits the facts?\"}],\"reference_example\":[\"He got busy at work.\",\"He planned to reply later and forgot.\",\"He is driving.\",\"His phone battery died.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Wait until the end of the workday.\\nIf there is still no reply, send one calm message:\\n\\\"Just checking if everything is okay. Call me when you\'re free.\\\"\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"A delayed reply is a fact. Being ignored is a story/assumptions until evidence proves otherwise.\"}],\"closing_reflection\":{\"prompt\":\"Where else in my life might I be confusing facts with stories?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-11-10 12:00:00', '2026-11-10 12:00:00')
ON DUPLICATE KEY UPDATE `title` = 'Read but No Reply', `domain` = 'Relationships', `primary_trap` = 'Mind Reading', `secondary_trap` = '', `content_bundle` = '{\"day\":1,\"phase\":1,\"title\":\"Read but No Reply\",\"domain\":\"Relationships\",\"mission\":\"Don\'t let your mind write the story before the facts.\",\"learning_objective\":\"Separate Facts from Stories\",\"difficulty\":\"Beginner\",\"emotional_intensity\":\"Low\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Detect\",\"primary_trap\":\"Mind Reading\",\"secondary_trap\":null,\"scenario_text\":\"Ananya sends her husband a message during lunch asking him to call when he is free.\\nHe reads the message.\\nThree hours pass.\\nThere is still no reply.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"Your brain creates stories automatically.\\nYour first responsibility is to separate them from facts.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story/assumptions your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: He read my message three hours ago and hasn\'t replied.\\nStory/assumptions: He is upset with me and is ignoring me.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"}],\"correct_option_key\":\"mind_reading\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Mind Reading.\\nThe only confirmed fact is that there has been no reply.\\nThe story is that he is upset and deliberately ignoring her.\\nThere is no evidence to support that conclusion.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask \\\"What happened?\\\" before asking \\\"How are you feeling?\\\" or \\\"What\'s bothering you?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one more explanation that also fits the facts?\"}],\"reference_example\":[\"He got busy at work.\",\"He planned to reply later and forgot.\",\"He is driving.\",\"His phone battery died.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Wait until the end of the workday.\\nIf there is still no reply, send one calm message:\\n\\\"Just checking if everything is okay. Call me when you\'re free.\\\"\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"A delayed reply is a fact. Being ignored is a story/assumptions until evidence proves otherwise.\"}],\"closing_reflection\":{\"prompt\":\"Where else in my life might I be confusing facts with stories?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-11-10 12:00:00';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (2, 1, 'Let\'s Meet Tomorrow', 'Workplace', 'Fortune Telling', '', '{\"day\":2,\"phase\":1,\"title\":\"Let\'s Meet Tomorrow\",\"domain\":\"Workplace\",\"mission\":\"Don\'t predict the future without evidence.\",\"learning_objective\":\"Recognize Thinking Traps\",\"difficulty\":\"Beginner\",\"emotional_intensity\":\"Low\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Decode\",\"primary_trap\":\"Fortune Telling\",\"secondary_trap\":null,\"scenario_text\":\"At 8:15 PM, your manager sends you a message:\\n\\\"Let\'s meet tomorrow morning.\\\"\\nThere is no agenda.\\nNo explanation.\\nNo follow-up message.\\nYou spend the rest of the evening wondering what the meeting is about.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"Your mind naturally tries to predict what happens next.\\nPredictions are not facts.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My manager asked to meet me tomorrow morning.\\nStory: I\'m probably in trouble or about to receive negative feedback.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"}],\"correct_option_key\":\"fortune_telling\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Fortune Telling.\\nNothing has happened yet.\\nYour mind has filled in the missing information by predicting an outcome without evidence.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask \\\"What happened?\\\" before asking \\\"How are you feeling?\\\" or \\\"What\'s bothering you?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one positive possibility that also fits the facts?\"}],\"reference_example\":[\"The manager wants to discuss a new project.\",\"The meeting is part of a routine review.\",\"The manager needs your input on an upcoming task.\",\"The manager prefers discussing something in person rather than over messages.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Avoid jumping to conclusions.\\nPrepare for the meeting as you normally would and wait until you have more information before interpreting the situation.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"An uncertain future is not evidence. Predictions should never be treated as facts.\"}],\"closing_reflection\":{\"prompt\":\"Where else today might I be predicting an outcome without enough evidence?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-11-10 12:00:00', '2026-11-10 12:00:00')
ON DUPLICATE KEY UPDATE `title` = 'Let\'s Meet Tomorrow', `domain` = 'Workplace', `primary_trap` = 'Fortune Telling', `secondary_trap` = '', `content_bundle` = '{\"day\":2,\"phase\":1,\"title\":\"Let\'s Meet Tomorrow\",\"domain\":\"Workplace\",\"mission\":\"Don\'t predict the future without evidence.\",\"learning_objective\":\"Recognize Thinking Traps\",\"difficulty\":\"Beginner\",\"emotional_intensity\":\"Low\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Decode\",\"primary_trap\":\"Fortune Telling\",\"secondary_trap\":null,\"scenario_text\":\"At 8:15 PM, your manager sends you a message:\\n\\\"Let\'s meet tomorrow morning.\\\"\\nThere is no agenda.\\nNo explanation.\\nNo follow-up message.\\nYou spend the rest of the evening wondering what the meeting is about.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"Your mind naturally tries to predict what happens next.\\nPredictions are not facts.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My manager asked to meet me tomorrow morning.\\nStory: I\'m probably in trouble or about to receive negative feedback.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"},{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"}],\"correct_option_key\":\"fortune_telling\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Fortune Telling.\\nNothing has happened yet.\\nYour mind has filled in the missing information by predicting an outcome without evidence.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask \\\"What happened?\\\" before asking \\\"How are you feeling?\\\" or \\\"What\'s bothering you?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one positive possibility that also fits the facts?\"}],\"reference_example\":[\"The manager wants to discuss a new project.\",\"The meeting is part of a routine review.\",\"The manager needs your input on an upcoming task.\",\"The manager prefers discussing something in person rather than over messages.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Avoid jumping to conclusions.\\nPrepare for the meeting as you normally would and wait until you have more information before interpreting the situation.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"An uncertain future is not evidence. Predictions should never be treated as facts.\"}],\"closing_reflection\":{\"prompt\":\"Where else today might I be predicting an outcome without enough evidence?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', `updated_at` = '2026-11-10 12:00:00';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (3, 1, 'The Different Tone', 'Family', 'Emotional Reasoning', '', '{\"day\":3,\"phase\":1,\"title\":\"The Different Tone\",\"domain\":\"Family\",\"mission\":\"Feelings are real. Conclusions need evidence.\",\"learning_objective\":\"Test Assumptions with Evidence\",\"difficulty\":\"Beginner\",\"emotional_intensity\":\"Low\",\"estimated_minutes\":\"3-5\",\"primary_skill\":\"Reality Check\",\"primary_trap\":\"Emotional Reasoning\",\"secondary_trap\":null,\"scenario_text\":\"During dinner, your father answers your question with just one word.\\nHe doesn\'t smile.\\nHe quietly continues eating.\\nThe rest of the family continues talking normally.\\nYou suddenly feel that he is upset with you.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"insight\":\"Your feelings may be genuine.\\nBut feelings are not evidence.\\nAlways separate what happened from what you believe it means.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story your mind is creating.\",\"multiline\":true}],\"reference_example\":\"Fact: My father answered briefly during dinner and didn\'t smile.\\nStory: He must be angry with me.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap is most likely at work?\",\"input_type\":\"single_choice\",\"options\":[{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"}],\"correct_option_key\":\"emotional_reasoning\",\"explanation_reveal\":\"after_selection\",\"explanation\":\"Why Emotional Reasoning.\\nFeeling worried doesn\'t automatically mean something is wrong.\\nThe feeling is real.\\nThe conclusion still needs evidence.\"},{\"step_number\":3,\"key\":\"reality_check\",\"tip\":\"Ask \\\"What happened?\\\" before asking \\\"How are you feeling?\\\" or \\\"What\'s bothering you?\\\"\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What fact do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What are you assuming?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your assumption?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence contradicts it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. If someone else described this situation, what would you tell them?\"}]},{\"step_number\":4,\"key\":\"reframe\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least 3 other explanations that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":3},{\"field_key\":\"one_more_explanation\",\"prompt\":\"Can you think of one explanation that has nothing to do with you?\"}],\"reference_example\":[\"He had a tiring day.\",\"He is thinking about something unrelated.\",\"He isn\'t feeling physically well.\",\"He simply isn\'t in the mood to talk much today.\"]},{\"step_number\":5,\"key\":\"intervention\",\"reminder\":\"There isn\'t always a perfect action.\\nThere is usually one reasonable action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available, what is one thoughtful action you can take?\"}],\"reference_example\":\"Rather than assuming something is wrong, wait for an appropriate moment and calmly ask:\\n\\\"You seemed quieter than usual today. Is everything okay?\\\"\\nThen listen without assuming the answer.\"},{\"step_number\":6,\"key\":\"internalize\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete this sentence: \\\"Today I learned that...\\\"\"}],\"reference_example\":\"Feeling worried doesn\'t prove that something is wrong. Feelings deserve attention, but conclusions require evidence.\"}],\"closing_reflection\":{\"prompt\":\"Where else in my life have I mistaken a feeling for a fact?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional journal entry — user may type or speak a personal reflection here (not scored).\",\"required\":false}}}', '2026-11-10 12:00:00', '2026-11-10 12:00:00')
