INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (26, 2, 'The Counteroffer', 'Career', 'Sunk Cost Fallacy', 'Validation Seeking, Confirmation Bias', '{\"day\":26,\"phase\":2,\"title\":\"The Counteroffer\",\"domain\":\"Career\",\"mission\":\"A counteroffer can change the numbers without changing the underlying problem.\",\"learning_objective\":\"Test Assumptions with Evidence\",\"difficulty\":\"Intermediate\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"4-6\",\"primary_skill\":\"Reality Check\",\"primary_trap\":\"Sunk Cost Fallacy\",\"secondary_trap\":\"Validation Seeking, Confirmation Bias\",\"secondary_traps\":[\"Validation Seeking\",\"Confirmation Bias\"],\"guidance_level\":\"Moderate-to-reduced guidance; user must defend the next action and work with competing information.\",\"interaction_principle\":\"Think → Commit → Defend → Compare → Reflect\",\"scenario_text\":\"You resign after months of frustration about limited growth.\\nYour employer immediately offers a significant salary increase and a new title.\\nYou feel valued for the first time in months.\\nYour manager says the growth concerns will be addressed.\\nYou now have to decide whether to stay or leave.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"prompt\":\"Before you interpret the situation, identify the facts, then state the story or conclusion your mind is moving toward.\",\"insight\":\"Facts describe what is known. The story explains what the mind thinks the facts mean.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story/assumptions your mind is creating.\",\"multiline\":true}],\"thinkclear_thinking\":{\"facts\":[\"You had decided to leave before the counteroffer.\",\"Your employer has offered more money and a new title.\",\"You had concerns about growth before the offer.\",\"Some future changes have been promised.\",\"You have another opportunity available.\"],\"story\":\"They finally recognize my value, so staying must be the right decision.\"},\"reference_example\":\"Fact: You had decided to leave before the counteroffer. Your employer has offered more money and a new title. You had concerns about growth before the offer. Some future changes have been promised. You have another opportunity available.\\nStory: They finally recognize my value, so staying must be the right decision.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap(s) may be influencing your judgment? Select the one you think is primary and note any others.\",\"input_type\":\"single_choice_with_multi_notes\",\"options\":[{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"},{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"},{\"key\":\"rumination\",\"label\":\"Rumination\",\"definition\":\"Repetitive, circular overthinking of past events.\"},{\"key\":\"all_or_nothing\",\"label\":\"All-or-Nothing Thinking\",\"definition\":\"Treating a minor gap as total failure or framing as either-or.\"},{\"key\":\"validation_seeking\",\"label\":\"Validation Seeking\",\"definition\":\"Allowing external approval to define self-worth or decisions.\"},{\"key\":\"sunk_cost_fallacy\",\"label\":\"Sunk Cost Fallacy\",\"definition\":\"Continuing a path solely because of past unrecoverable investment.\"}],\"correct_option_key\":\"sunk_cost_fallacy\",\"primary_trap\":\"Sunk Cost Fallacy\",\"secondary_traps\":[\"Validation Seeking\",\"Confirmation Bias\"],\"secondary_trap_keys\":[\"validation_seeking\",\"confirmation_bias\"],\"explanation_reveal\":\"after_commit\",\"explanation\":\"Sunk Cost can pull you back into the familiar path simply because of your history. Validation Seeking may make the recognition feel like proof that the organization has changed. Confirmation Bias can selectively favor whichever option feels emotionally satisfying.\\nRemember: More than one thinking trap can exist in the same situation. The goal is not to label yourself; it is to identify what may be distorting the decision.\"},{\"step_number\":3,\"key\":\"reality_check\",\"prompt\":\"Answer these questions before deciding what the situation means:\\n• What facts do you know for certain?\\n• What assumptions are you making?\\n• What evidence supports your conclusion?\\n• What evidence challenges it?\\n• What information is still missing?\",\"tip\":\"Missing information is not evidence. Identify what you would need to know before becoming more certain.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What facts do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What assumptions are you making?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your conclusion?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence challenges it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What information is still missing?\"}],\"thinkclear_thinking\":[\"The salary has changed.\",\"The title has changed.\",\"I need to verify what will actually change in role, authority and growth.\",\"The original problems may or may not be resolved.\"],\"reference_example\":[\"The salary has changed.\",\"The title has changed.\",\"I need to verify what will actually change in role, authority and growth.\",\"The original problems may or may not be resolved.\"]},{\"step_number\":4,\"key\":\"reframe\",\"prompt\":\"Generate at least four plausible alternatives. At least one should challenge your first interpretation.\",\"insight\":\"Reframing does not mean forcing a positive interpretation. It means expanding the set of explanations or options before deciding.\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least four other explanations or perspectives that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":4}],\"thinkclear_thinking\":[\"The counteroffer may genuinely solve the problem.\",\"The counteroffer may address compensation but not development.\",\"The external opportunity may offer a different learning path.\",\"I may be able to negotiate specific conditions before deciding.\"],\"reference_example\":[\"The counteroffer may genuinely solve the problem.\",\"The counteroffer may address compensation but not development.\",\"The external opportunity may offer a different learning path.\",\"I may be able to negotiate specific conditions before deciding.\"]},{\"step_number\":5,\"key\":\"intervention\",\"prompt\":\"Choose one reasonable next action. Explain what it will help you learn, clarify or protect.\",\"reminder\":\"There isn\'t always a perfect action. There is usually a reasonable next action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available today, what is the most reasonable next action?\"}],\"thinkclear_thinking\":[\"Compare both roles on the factors that originally led to the resignation.\",\"Get important promises documented where appropriate.\",\"Decide based on future fit rather than the emotional effect of being retained.\"],\"reference_example\":\"Compare both roles on the factors that originally led to the resignation.\\nGet important promises documented where appropriate.\\nDecide based on future fit rather than the emotional effect of being retained.\"},{\"step_number\":6,\"key\":\"internalize\",\"prompt\":\"Complete the sentence: “Today I learned that…”\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete the sentence: “Today I learned that…”\"}],\"thinkclear_thinking\":\"Feeling valued is meaningful, but I still need to evaluate whether the underlying conditions have changed.\",\"reference_example\":\"Feeling valued is meaningful, but I still need to evaluate whether the underlying conditions have changed.\"}],\"closing_reflection\":{\"prompt\":\"If the counteroffer had no salary increase, what would you think about the underlying job?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional reflection entry — take a moment to reflect on today\'s scenario.\",\"required\":false}}}', '2026-11-10 12:00:00', '2026-11-10 12:00:00')
